import{_ as d,o as i,c as e,a4 as n}from"./chunks/framework.vNSRaLQv.js";const p=JSON.parse('{"title":"HomeSense NLI 方向判定模型测试报告（MiniLMv2-XNLI）","description":"","frontmatter":{"title":"HomeSense NLI 方向判定模型测试报告（MiniLMv2-XNLI）","date":"2026-09-02T00:00:00.000Z"},"headers":[],"relativePath":"posts/HomeSense-L2-NLI模型测试报告.md","filePath":"posts/HomeSense-L2-NLI模型测试报告.md"}'),a={name:"posts/HomeSense-L2-NLI模型测试报告.md"};function o(s,t,r,l,h,c){return i(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="homesense-nli-方向判定模型测试报告-minilmv2-xnli" tabindex="-1">HomeSense NLI 方向判定模型测试报告（MiniLMv2-XNLI） <a class="header-anchor" href="#homesense-nli-方向判定模型测试报告-minilmv2-xnli" aria-label="Permalink to &quot;HomeSense NLI 方向判定模型测试报告（MiniLMv2-XNLI）&quot;">​</a></h1><blockquote><p>日期：2026-09-02 模型：<code>onnx-community/multilingual-MiniLMv2-L6-mnli-xnli-ONNX</code>（int8） 格式：XLMRobertaForSequenceClassification，输入 <code>input_ids</code>+<code>attention_mask</code>，输出 <code>logits</code>(3类) 体积：107MB（单文件，无外部数据） 测试环境：本机 x86_64，onnxruntime-purego（纯 Go，无 cgo）</p></blockquote><hr><h2 id="_1-背景" tabindex="-1">1. 背景 <a class="header-anchor" href="#_1-背景" aria-label="Permalink to &quot;1. 背景&quot;">​</a></h2><p>为缓解 v2 混合检索的方向性硬伤（反义误报：熄灯→开灯、放大→调小），调研业界用 <strong>NLI（自然语言推理）模型</strong>做方向校准：判定 query 与候选意图是「蕴含 / 矛盾 / 中立」。</p><p>对比过的中文 NLI 现成模型：</p><table tabindex="0"><thead><tr><th>模型</th><th>语言</th><th>ONNX?</th><th>大小</th><th>结论</th></tr></thead><tbody><tr><td>IDEA-CCNL/Erlangshen-Roberta-110M-NLI</td><td>中文</td><td>❌ 仅 pytorch</td><td>409MB</td><td>无法跑</td></tr><tr><td>uer/sbert-base-chinese-nli</td><td>中文</td><td>❌ 仅 pytorch</td><td>-</td><td>无法跑</td></tr><tr><td>onnx-community/EttinX-nli-xxs</td><td>英文</td><td>✅</td><td>17MB</td><td>中文不支持</td></tr><tr><td>onnx-community/multilingual-nli-bert</td><td>多语含zh</td><td>✅</td><td>179MB</td><td>可用但大</td></tr><tr><td><strong>multilingual-MiniLMv2-L6-mnli-xnli</strong></td><td>多语含zh</td><td>✅</td><td><strong>107MB</strong></td><td><strong>选用（最小中文可用）</strong></td></tr></tbody></table><hr><h2 id="_2-调用方式验证" tabindex="-1">2. 调用方式验证 <a class="header-anchor" href="#_2-调用方式验证" aria-label="Permalink to &quot;2. 调用方式验证&quot;">​</a></h2><p>model card 官方用法（NLI）：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">tokenizer</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">(</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">premise</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">,</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> hypothesis</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">,</span><span style="--shiki-light:#B07D48;--shiki-dark:#BD976A;"> truncation</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">=</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">True</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">)</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">  # &lt;s&gt; premise &lt;/s&gt;&lt;/s&gt; hypothesis &lt;/s&gt;</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">output </span><span style="--shiki-light:#999999;--shiki-dark:#666666;">=</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> model</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">(</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">input_ids</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">)</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">  → logits → softmax → </span><span style="--shiki-light:#999999;--shiki-dark:#666666;">[</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">entailment</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">,</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> neutral</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">,</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> contradiction</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">]</span></span></code></pre></div><p>Go 端实现：</p><ul><li><code>tok.Encode(tokenizer.NewDualEncodeInput(NewInputSequence(premise), NewInputSequence(hypothesis)), true)</code> 生成 <code>&lt;s&gt; A &lt;/s&gt;&lt;/s&gt; B &lt;/s&gt;</code> ✅</li><li>输入 <code>input_ids</code> + <code>attention_mask</code>，输出取 <code>logits</code> → softmax → 3 类 ✅</li><li>验证 IO：<code>inputs=[input_ids attention_mask] outputs=[logits]</code> ✅</li></ul><p><strong>调用方式完全正确，不是误用。</strong></p><hr><h2 id="_3-速度实测-x86-64-本机-含-tokenize-intraopnumthreads-4" tabindex="-1">3. 速度实测（x86_64 本机，含 tokenize，IntraOpNumThreads=4） <a class="header-anchor" href="#_3-速度实测-x86-64-本机-含-tokenize-intraopnumthreads-4" aria-label="Permalink to &quot;3. 速度实测（x86_64 本机，含 tokenize，IntraOpNumThreads=4）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>maxLen</th><th>平均延迟</th></tr></thead><tbody><tr><td>32</td><td><strong>4.6 ms</strong></td></tr><tr><td>64</td><td><strong>6.7 ms</strong></td></tr><tr><td>128</td><td><strong>11.7 ms</strong></td></tr><tr><td>长句 128</td><td><strong>12.3 ms</strong></td></tr></tbody></table><p>比 bge embedding（~33ms）还快。ARM64 手机预估放大 2-4 倍 ≈ 30-50ms。<strong>速度完全不是问题。</strong></p><hr><h2 id="_4-方向判定质量实测-18-组" tabindex="-1">4. 方向判定质量实测（18 组） <a class="header-anchor" href="#_4-方向判定质量实测-18-组" aria-label="Permalink to &quot;4. 方向判定质量实测（18 组）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>premise</th><th>hypothesis</th><th>E</th><th>N</th><th>C</th><th>判定</th><th>期望</th><th>正确?</th></tr></thead><tbody><tr><td>把声音放大</td><td>调高音量</td><td>0.33</td><td>0.57</td><td>0.10</td><td>neutral</td><td>entail</td><td>❌</td></tr><tr><td>把声音放大</td><td>调低音量</td><td>0.13</td><td>0.45</td><td>0.43</td><td>neutral</td><td>contradiction</td><td>⚠️方向可区分但不够</td></tr><tr><td>大声点</td><td>调高音量</td><td>0.33</td><td>0.58</td><td>0.09</td><td>neutral</td><td>entail</td><td>❌</td></tr><tr><td>小声点</td><td>调低音量</td><td>0.14</td><td>0.47</td><td>0.39</td><td>neutral</td><td>entail</td><td>❌</td></tr><tr><td><strong>熄灯</strong></td><td><strong>关灯</strong></td><td>0.23</td><td>0.19</td><td><strong>0.58</strong></td><td><strong>contradiction</strong></td><td>entail</td><td><strong>❌ 熄=关 判成矛盾</strong></td></tr><tr><td>熄灯</td><td>开灯</td><td>0.14</td><td>0.09</td><td>0.77</td><td>contradiction</td><td>contradiction</td><td>✅</td></tr><tr><td>把客厅灯灭了</td><td>关客厅灯</td><td>0.47</td><td>0.39</td><td>0.14</td><td>entail</td><td>entail</td><td>✅</td></tr><tr><td><strong>把客厅灯灭了</strong></td><td><strong>开客厅灯</strong></td><td><strong>0.51</strong></td><td>0.36</td><td>0.13</td><td><strong>entail</strong></td><td>contradiction</td><td><strong>❌ 反义判成蕴含</strong></td></tr><tr><td>我到家了</td><td>回家模式</td><td>0.22</td><td>0.63</td><td>0.15</td><td>neutral</td><td>entail</td><td>⚠️弱</td></tr><tr><td>我要出门了</td><td>离家模式</td><td>0.28</td><td>0.42</td><td>0.31</td><td>neutral</td><td>entail</td><td>⚠️弱</td></tr><tr><td>我要出门了</td><td>回家模式</td><td>0.27</td><td>0.57</td><td>0.16</td><td>neutral</td><td>contradiction</td><td>⚠️弱</td></tr><tr><td>回家</td><td>回家模式</td><td>0.61</td><td>0.31</td><td>0.08</td><td>entail</td><td>entail</td><td>✅</td></tr><tr><td>开冷气</td><td>开空调</td><td>0.31</td><td>0.50</td><td>0.19</td><td>neutral</td><td>entail</td><td>❌弱</td></tr><tr><td>投屏到电视</td><td>投屏</td><td>0.47</td><td>0.22</td><td>0.30</td><td>entail</td><td>entail</td><td>✅</td></tr><tr><td>投屏到电视</td><td>关电视</td><td>0.40</td><td>0.35</td><td>0.25</td><td>entail</td><td>neutral</td><td>❌</td></tr><tr><td>打开电视</td><td>开空调</td><td>0.16</td><td>0.62</td><td>0.21</td><td>neutral</td><td>neutral</td><td>✅</td></tr><tr><td>今天天气怎么样</td><td>回家模式</td><td>0.10</td><td>0.75</td><td>0.15</td><td>neutral</td><td>neutral</td><td>✅</td></tr><tr><td>帮我订个外卖</td><td>投屏</td><td>0.17</td><td>0.11</td><td>0.73</td><td>contradiction</td><td>contradiction</td><td>✅</td></tr></tbody></table><hr><h2 id="_5-结论-不粉饰" tabindex="-1">5. 结论（不粉饰） <a class="header-anchor" href="#_5-结论-不粉饰" aria-label="Permalink to &quot;5. 结论（不粉饰）&quot;">​</a></h2><h3 id="_5-1-能力上限" tabindex="-1">5.1 能力上限 <a class="header-anchor" href="#_5-1-能力上限" aria-label="Permalink to &quot;5.1 能力上限&quot;">​</a></h3><ul><li>model card 明示 XNLI 平均准确率仅 <strong>0.71</strong>（15 语言平均），且作者推荐更高性能用 mDeBERTa-v3-base</li><li>对<strong>中文超短口语短语（熄灯/小声点/灭了）是盲区</strong>： <ul><li>熄灯 → 关灯 被判 <strong>contradiction</strong>（大错）</li><li>把客厅灯灭了 → 开客厅灯 被判 <strong>entail</strong>（反义判成蕴含）</li></ul></li><li>单独当硬 gate 会引入<strong>新的误判</strong>，不比现有 hard-negative 方案强</li></ul><h3 id="_5-2-速度" tabindex="-1">5.2 速度 <a class="header-anchor" href="#_5-2-速度" aria-label="Permalink to &quot;5.2 速度&quot;">​</a></h3><ul><li>107MB int8，x86 6-12ms/次，速度完全够用（非瓶颈）</li></ul><h3 id="_5-3-部署代价" tabindex="-1">5.3 部署代价 <a class="header-anchor" href="#_5-3-部署代价" aria-label="Permalink to &quot;5.3 部署代价&quot;">​</a></h3><ul><li>体积 42MB → 149MB（+107MB）</li><li>结论：<strong>速度可接受，但能力上限（0.71）撑不起方向性硬裁决</strong></li></ul><hr><h2 id="_6-后续选项" tabindex="-1">6. 后续选项 <a class="header-anchor" href="#_6-后续选项" aria-label="Permalink to &quot;6. 后续选项&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>速度</th><th>体积</th><th>方向性效果</th></tr></thead><tbody><tr><td>A. MiniLM 当软校准（与 embedding 加权，不当唯一裁判）</td><td>+7ms</td><td>+107MB</td><td>⚠️ 有改善但不稳</td></tr><tr><td>B. mDeBERTa-v3-base NLI</td><td>❌ 见 7</td><td>❌</td><td>❌ 开箱即用的 ONNX 导出不可用</td></tr><tr><td>C. hard-negative 逐个钉方向坑（零新增）</td><td>0</td><td>0</td><td>⚠️ 治标，已知坑有效</td></tr><tr><td>D. 高置信本地 / 低置信云端 LLM（业界混合路由）</td><td>-</td><td>-</td><td>✅ 最终形态</td></tr></tbody></table><hr><h2 id="_7-mdeberta-v3-base-实测追击记录-b-方案彻底否决" tabindex="-1">7. mDeBERTa-v3-base 实测追击记录（B 方案彻底否决） <a class="header-anchor" href="#_7-mdeberta-v3-base-实测追击记录-b-方案彻底否决" aria-label="Permalink to &quot;7. mDeBERTa-v3-base 实测追击记录（B 方案彻底否决）&quot;">​</a></h2><blockquote><p>追加：2026-09-02 晚。MiniLM 不够用时一度想上 mDeBERTa-v3-base（XNLI 中文 accuracy 0.803），对开箱即用的 ONNX 版本做了实测，<strong>结论是此路不通，已正式移除 B 方案。</strong></p></blockquote><h3 id="_7-1-下载与体积" tabindex="-1">7.1 下载与体积 <a class="header-anchor" href="#_7-1-下载与体积" aria-label="Permalink to &quot;7.1 下载与体积&quot;">​</a></h3><ul><li>仓库 <code>onnx-community/mDeBERTa-v3-base-xnli-multilingual-nli-2mil7-ONNX</code></li><li><code>onnx/model_int8.onnx</code> = 338MB（int8）；<code>model.onnx</code> = 566MB（fp32）</li><li><strong>下载走 hf-mirror.com 镜像，~2MB/s，curl 顺畅</strong>（浏览器/hf_hub 直连 huggingface.co 国内不可用）</li></ul><h3 id="_7-2-架构差异-disentangled-relative-position" tabindex="-1">7.2 架构差异（Disentangled Relative Position） <a class="header-anchor" href="#_7-2-架构差异-disentangled-relative-position" aria-label="Permalink to &quot;7.2 架构差异（Disentangled Relative Position）&quot;">​</a></h3><ul><li>config：<code>model_type=deberta-v2</code>，<code>type_vocab_size=0</code>，12 层，hidden 768</li><li>ONNX 图输入：<strong>只有 <code>input_ids</code> + <code>attention_mask</code></strong>（无 <code>token_type_ids</code>）</li><li>查证：导出器在 <code>type_vocab_size==0</code> 时会<strong>主动删除</strong> token_type_ids → 图里没有它<strong>是正常导出</strong>，不是漏传。但代价是 DeBERTa 原版用于区分两段话语的 disentangled relative position 信息在 ONNX 图中先天残缺</li></ul><h3 id="_7-3-速度实测-本机-x86-64-int8-含-tokenize-4-线程" tabindex="-1">7.3 速度实测（本机 x86_64，int8，含 tokenize，4 线程） <a class="header-anchor" href="#_7-3-速度实测-本机-x86-64-int8-含-tokenize-4-线程" aria-label="Permalink to &quot;7.3 速度实测（本机 x86_64，int8，含 tokenize，4 线程）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>maxLen</th><th>mDeBERTa-base（12层，338MB）</th><th>MiniLM-L6（6层，107MB）</th><th>倍数</th></tr></thead><tbody><tr><td>32</td><td><strong>31.7 ms</strong></td><td>3.4 ms</td><td>~9x</td></tr><tr><td>64</td><td><strong>59.0 ms</strong></td><td>6.0 ms</td><td>~10x</td></tr><tr><td>128</td><td><strong>121.6 ms</strong></td><td>11.4 ms</td><td>~11x</td></tr></tbody></table><ul><li>速度是致命伤：12 层 attention + disentangled 每层加一个位置计算，延迟几乎随句长线性翻倍</li><li>手机 ARM 再放大 2-4x → 家宽指令（64）约 120-240ms，已超短口语输入的手感阈值</li></ul><h3 id="_7-4-方向判定质量-18-组同款样例-——-输出退化" tabindex="-1">7.4 方向判定质量（18 组同款样例）—— 输出退化 <a class="header-anchor" href="#_7-4-方向判定质量-18-组同款样例-——-输出退化" aria-label="Permalink to &quot;7.4 方向判定质量（18 组同款样例）—— 输出退化&quot;">​</a></h3><p>全部 18 组样例结果几乎相同，<strong>分类头对输入几乎不响应</strong>：</p><table tabindex="0"><thead><tr><th>premise</th><th>hypothesis</th><th>E</th><th>N</th><th>C</th></tr></thead><tbody><tr><td>熄灯</td><td>开灯（应矛盾）</td><td>0.52</td><td>0.47</td><td><strong>0.01</strong></td></tr><tr><td>熄灯</td><td>关灯（应蕴含）</td><td>0.47</td><td>0.52</td><td><strong>0.01</strong></td></tr><tr><td>把声音放大</td><td>调高音量（应蕴含）</td><td>0.56</td><td>0.44</td><td>0.01</td></tr><tr><td>把声音放大</td><td>调低音量（应矛盾）</td><td>0.55</td><td>0.45</td><td>0.01</td></tr><tr><td>帮我订个外卖</td><td>投屏（应矛盾）</td><td>0.51</td><td>0.48</td><td>0.01</td></tr></tbody></table><ul><li>raw logits：entail/neutral 只在 1.37~1.65 区间微动，<strong>contradiction logit 被恒定钳在 -2.7 附近</strong> → softmax 后 C 恒为 ~0.01</li><li>MiniLM 同路径、同代码能给出极化区分（熄灯→开灯 C=0.77），且 Python tokenizers 复现了完全一致的退化结果 → <strong>不是 Go 代码、不是 tokenizer 用法问题</strong></li><li>单句输入 vs 双句输入输出几乎相同 → <strong>int8 量化把分类头压扁，contradiction 门死亡</strong></li></ul><h3 id="_7-5-关键否决依据-模型卡原文-导出机制" tabindex="-1">7.5 关键否决依据（模型卡原文 + 导出机制） <a class="header-anchor" href="#_7-5-关键否决依据-模型卡原文-导出机制" aria-label="Permalink to &quot;7.5 关键否决依据（模型卡原文 + 导出机制）&quot;">​</a></h3><ul><li>模型卡原文：<strong>&quot;mDeBERTa currently does not support FP16&quot;</strong> → fp16 版不可用；fp32 原始权重 2GB+，手机存不下</li><li>XNLI 中文 accuracy 0.803 是<strong>长句基准</strong>成绩，非超短口语短语</li><li>int8 量化退化 + ONNX 导出缺失 relative-position 信息双重打击 → <strong>现成 ONNX 无法直接裁决最需要的「反义」</strong></li></ul><h3 id="_7-6-新结论" tabindex="-1">7.6 新结论 <a class="header-anchor" href="#_7-6-新结论" aria-label="Permalink to &quot;7.6 新结论&quot;">​</a></h3><ol><li><strong>mDeBERTa ONNX 这条路整体关闭</strong>。不是慢不慢的问题，是现成 int8 导出质量不行（分类头退化）</li><li>要用 mDeBERTa 必须自己做 fp32→int8 重新校准量化，且仍受 TypeVocabSize=0 导出限制 → 投入产出比差</li><li><strong>NLI 模型线（MiniLM / mDeBERTa）均不采用</strong>，方向性回到<strong>规则硬钉</strong>（方案 C），云端 LLM 路由（方案 D）作为长期形态</li><li>教训：<strong>下大文件（&gt;300MB）用 <code>hf-mirror.com</code> + <code>curl -L</code> 带断点续传，别用浏览器直连 huggingface.co</strong></li></ol><hr><h2 id="_8-相关文件" tabindex="-1">8. 相关文件 <a class="header-anchor" href="#_8-相关文件" aria-label="Permalink to &quot;8. 相关文件&quot;">​</a></h2><ul><li>模型：<code>/tmp/minilm-nli/model_nli_int8.onnx</code> + <code>tokenizer.json</code> + <code>config.json</code>（MiniLM，保留）</li><li>mDeBERTa：<code>/tmp/mdeberta-nli/</code>（int8 338MB，结论不可用，可删）</li><li>测试：<code>/tmp/nli-bench/</code>（<code>infer</code> 方向判定、<code>bench</code> 延迟）</li><li>模型源：<code>onnx-community/multilingual-MiniLMv2-L6-mnli-xnli-ONNX</code>；<code>onnx-community/mDeBERTa-v3-base-xnli-multilingual-nli-2mil7-ONNX</code></li><li>姊妹篇：<code>~/Desktop/HomeSense-L2-混合检索测试报告.md</code></li></ul>`,53)])])}const u=d(a,[["render",o]]);export{p as __pageData,u as default};
